const cmds = [
  ["audit-input", "sed -n '1,260p' /audit-input.json", "/audit-output"],
  ["campaign-lock", "sed -n '1,260p' /audit-campaign-lock.json", "/audit-output"],
  ["tree", "find /candidate /reference /generation-evidence -maxdepth 4 -printf '%y %s %p -> %l\\n' | sort", "/audit-output"],
  ["required-records", "stat -c '%F %s %n' /run.json /task.json /generation-result.json /generation-evidence/invocation.json /generation-evidence/metrics.json /generation-evidence/runtime-metrics.json /generation-evidence/usage.json /generation-evidence/codex-last.txt /generation-evidence/codex-output.log /generation-evidence/prompt.txt", "/audit-output"],
  ["trace", "find /generation-evidence/codex-trace -printf '%y %s %p -> %l\\n' | sort", "/audit-output"]
];
const results = await Promise.all(cmds.map(async ([label, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:30000});
  return {label, ...r};
}));
for (const r of results) {
  text(JSON.stringify(r));
}

const cmds = [
  ["records", "for f in /run.json /task.json /generation-result.json /generation-evidence/invocation.json /generation-evidence/metrics.json /generation-evidence/usage.json /generation-evidence/codex-last.txt /generation-evidence/prompt.txt; do sed -n '1,260p' \"$f\"; done", "/audit-output"],
  ["hashes", "sha256sum /audit-campaign-lock.json /reference/canonical.py /reference/prompt.py /reference/py2mpy.py /candidate/prompt.py /candidate/py2mpy.py /run.json /task.json /generation-result.json /generation-evidence/invocation.json /generation-evidence/metrics.json /generation-evidence/usage.json /generation-evidence/codex-last.txt /generation-evidence/codex-output.log /generation-evidence/prompt.txt /generation-evidence/codex-trace/2026/07/22/*.jsonl", "/audit-output"],
  ["semantics-integrity", "diff --no-dereference -rqs /reference/reference-semantics /candidate/reference-semantics; find /reference/reference-semantics /candidate/reference-semantics -type l -printf '%p -> %l\\n'; find /reference/reference-semantics -printf '%P %y %m %s\\n' | sort; find /candidate/reference-semantics -printf '%P %y %m %s\\n' | sort", "/audit-output"],
  ["candidate-integrity", "cmp -s /candidate/prompt.py /reference/prompt.py; printf 'prompt_cmp_exit=%s\\n' \"$?\"; cmp -s /candidate/py2mpy.py /reference/py2mpy.py; printf 'translator_cmp_exit=%s\\n' \"$?\"; find /candidate -maxdepth 1 -type l -printf '%p -> %l\\n'; stat -c '%F %a %s %n' /candidate/solution.py /candidate/solution.mpy /candidate/spec.k /candidate/verification.k /candidate/prove.sh", "/audit-output"],
  ["scratch", "find /tmp/audit-work -mindepth 1 -maxdepth 2 -printf '%y %p -> %l\\n' | sort | sed -n '1,240p'", "/audit-output"]
];
const results = await Promise.all(cmds.map(async ([label, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:30000});
  return {label, exit_code:r.exit_code, output:r.output};
}));
for (const r of results) text(JSON.stringify(r));

const cmds = [
  ["candidate-sources", "for f in /candidate/solution.py /candidate/solution.mpy /candidate/spec.k /candidate/verification.k /candidate/prove.sh /candidate/concrete-tests.py /candidate/concrete-tests.mpy; do nl -ba \"$f\"; done", "/audit-output"],
  ["trusted-contract", "for f in /reference/prompt.py /reference/canonical.py; do nl -ba \"$f\"; done", "/audit-output"],
  ["generation-claims", "rg -n -C 3 'solution\\.py|solution\\.mpy|verification\\.k|spec\\.k|prove\\.sh|kprove|kompile|krun|#Top|WarnStuck|KPROVE_PASSED|spec-vacuity|loop' /generation-evidence/codex-output.log | sed -n '1,3000p'", "/audit-output"],
  ["trace-shape", "wc -l -c /generation-evidence/codex-output.log /generation-evidence/codex-trace/2026/07/22/*.jsonl; sed -n '1,8p' /generation-evidence/codex-trace/2026/07/22/*.jsonl; tail -n 8 /generation-evidence/codex-trace/2026/07/22/*.jsonl", "/audit-output"]
];
const results = await Promise.all(cmds.map(async ([label, cmd, workdir]) => {
  const r = await tools.exec_command({cmd, workdir, yield_time_ms:10000, max_output_tokens:50000});
  return {label, exit_code:r.exit_code, original_token_count:r.original_token_count, output:r.output};
}));
for (const r of results) text(JSON.stringify(r));

const filesA = [
  "/tmp/audit-work/reconstruction/reference-semantics/semantics.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/syntax.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/core.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/functions.k"
];
const filesB = [
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/call.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/controls.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/operators.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/int.k",
  "/tmp/audit-work/reconstruction/reference-semantics/semantics/list.k"
];
const run = async (label, files) => {
  const cmd = files.map(f => `nl -ba ${f}`).join("\n");
  const r = await tools.exec_command({cmd, workdir:"/audit-output", yield_time_ms:10000, max_output_tokens:50000});
  return {label, exit_code:r.exit_code, output:r.output};
};
const [a,b] = await Promise.all([run("semantics-core", filesA), run("used-domains", filesB)]);
text(JSON.stringify(a));
text(JSON.stringify(b));

